def fmt(minutes):
    minutes %= 1440
    h = minutes // 60
    m = minutes % 60
    period = "AM" if minutes < 12 * 60 else "PM"
    if h == 0:
        h = 12
    elif h > 12:
        h -= 12
    return f"{h}:{m:02d}{period}"

def fmt(t):
    period = 'AM' if t < 720 or t >= 1080 else 'PM'
    hour = t // 60
    if hour == 0:
        h12 = 12
    elif hour < 12:
        h12 = hour
    elif hour == 12:
        h12 = 12
    else:
        h12 = hour - 12
    return f"{h12}:{t % 60:02d}{period}"

